// Package config lee y valida las variables de entorno del binario.
package config

import (
	"errors"
	"fmt"
	"strconv"
	"strings"
	"time"
)

const sesionPorDefecto = 8 * time.Hour

// Config son los valores de entorno ya validados.
type Config struct {
	DatabaseURL  string
	ExcelPath    string
	SessionTTL   time.Duration
	CookieSecure bool
}

// Cargar lee la configuracion con la funcion de busqueda dada (os.LookupEnv en produccion).
// Reporta todos los problemas juntos, no solo el primero.
func Cargar(lookup func(string) (string, bool)) (*Config, error) {
	var problemas []string
	obtener := func(nombre string) string {
		v, _ := lookup(nombre)
		return strings.TrimSpace(v)
	}
	requerida := func(nombre string) string {
		v := obtener(nombre)
		if v == "" {
			problemas = append(problemas, fmt.Sprintf("falta la variable %s", nombre))
		}
		return v
	}

	cfg := &Config{
		DatabaseURL:  requerida("DATABASE_URL"),
		ExcelPath:    requerida("EXCEL_PATH"),
		SessionTTL:   sesionPorDefecto,
		CookieSecure: false,
	}

	if v := obtener("SESSION_TTL"); v != "" {
		d, err := time.ParseDuration(v)
		if err != nil || d <= 0 {
			problemas = append(problemas, fmt.Sprintf("SESSION_TTL=%q no es una duracion positiva (ejemplo: 8h)", v))
		} else {
			cfg.SessionTTL = d
		}
	}
	if v := obtener("COOKIE_SECURE"); v != "" {
		b, err := strconv.ParseBool(v)
		if err != nil {
			problemas = append(problemas, fmt.Sprintf("COOKIE_SECURE=%q no es true ni false", v))
		} else {
			cfg.CookieSecure = b
		}
	}

	if len(problemas) > 0 {
		return nil, errors.New("configuracion invalida: " + strings.Join(problemas, "; "))
	}
	return cfg, nil
}
EOF
cat > internal/config/config_test.go <<'EOF'
package config

import (
	"strings"
	"testing"
	"time"
)

func entorno(m map[string]string) func(string) (string, bool) {
	return func(k string) (string, bool) {
		v, ok := m[k]
		return v, ok
	}
}

func TestCargarValoresPorDefecto(t *testing.T) {
	cfg, err := Cargar(entorno(map[string]string{
		"DATABASE_URL": "postgres://u:p@db:5432/x",
		"EXCEL_PATH":   "/app/data/x.xlsx",
	}))
	if err != nil {
		t.Fatalf("error inesperado: %v", err)
	}
	if cfg.SessionTTL != 8*time.Hour {
		t.Errorf("SessionTTL = %v, se esperaba 8h", cfg.SessionTTL)
	}
	if cfg.CookieSecure {
		t.Error("CookieSecure deberia ser false por defecto")
	}
}

func TestCargarValoresExplicitos(t *testing.T) {
	cfg, err := Cargar(entorno(map[string]string{
		"DATABASE_URL":  "postgres://u:p@db:5432/x",
		"EXCEL_PATH":    "/app/data/x.xlsx",
		"SESSION_TTL":   "30m",
		"COOKIE_SECURE": "true",
	}))
	if err != nil {
		t.Fatalf("error inesperado: %v", err)
	}
	if cfg.SessionTTL != 30*time.Minute || !cfg.CookieSecure {
		t.Errorf("valores mal leidos: %+v", cfg)
	}
}

func TestCargarFaltantesSeReportanJuntos(t *testing.T) {
	_, err := Cargar(entorno(map[string]string{"DATABASE_URL": "   "}))
	if err == nil {
		t.Fatal("se esperaba error")
	}
	for _, esperado := range []string{"DATABASE_URL", "EXCEL_PATH"} {
		if !strings.Contains(err.Error(), "falta la variable "+esperado) {
			t.Errorf("el mensaje no menciona %s: %v", esperado, err)
		}
	}
}

func TestCargarValoresInvalidos(t *testing.T) {
	base := map[string]string{"DATABASE_URL": "x", "EXCEL_PATH": "y"}
	casos := map[string]string{
		"SESSION_TTL":   "ocho horas",
		"COOKIE_SECURE": "quizas",
	}
	for nombre, valor := range casos {
		env := map[string]string{}
		for k, v := range base {
			env[k] = v
		}
		env[nombre] = valor
		_, err := Cargar(entorno(env))
		if err == nil || !strings.Contains(err.Error(), nombre) {
			t.Errorf("%s=%q: se esperaba error que mencione la variable, llego %v", nombre, valor, err)
		}
	}
	env := map[string]string{"DATABASE_URL": "x", "EXCEL_PATH": "y", "SESSION_TTL": "-1h"}
	if _, err := Cargar(entorno(env)); err == nil {
		t.Error("una duracion negativa deberia fallar")
	}
}
